  seen.add(id)
  const node = api[id]
  if (!node || typeof node !== 'object') return false
  if (/^Empty.*Latent$/i.test(String(node.class_type))) return true
  if (!/Latent|VAEEncode|Sampler/i.test(String(node.class_type))) return false
  return Object.entries(node.inputs ?? {})
    .some(([key, value]) => /latent|samples|pixels/i.test(key) && startsFromEmptyLatent(api, value, seen))
